from django.contrib.auth.signals import (    user_logged_in,    user_logged_out,    user_login_failed)from django.dispatch import receiverfrom django.utils.timezone import nowfrom django.contrib.auth import get_user_modelfrom user_agents import parseimport requestsfrom .models import LoginLogoutDeviceLogUser = get_user_model()# =====================================================# GET CLIENT IP# =====================================================def get_client_ip(request):    if not request:        return ""    x_forwarded_for = request.META.get("HTTP_X_FORWARDED_FOR")    if x_forwarded_for:        ip = x_forwarded_for.split(",")[0].strip()    else:        ip = request.META.get("REMOTE_ADDR", "")    return ip# =====================================================# GET IP LOCATION# =====================================================def get_ip_location(ip):    if not ip or ip in ["127.0.0.1", "::1"]:        return {            "country": "Localhost",            "state": "",            "city": "",            "timezone": "Asia/Kolkata",        }    try:        url = f"http://ip-api.com/json/{ip}"        response = requests.get(url, timeout=3)        data = response.json()        if data.get("status") == "success":            return {                "country": data.get("country", ""),                "state": data.get("regionName", ""),                "city": data.get("city", ""),                "timezone": data.get("timezone", ""),            }    except Exception:        pass    return {        "country": "",        "state": "",        "city": "",        "timezone": "",    }# =====================================================# GET DEVICE INFO# =====================================================def get_device_info(request):    if not request:        return {            "device_name": "Unknown Device",            "device_type": "Desktop",            "browser": "Unknown Browser",            "browser_version": "",            "operating_system": "Unknown OS",            "os_version": "",            "user_agent": "",        }    user_agent_string = request.META.get("HTTP_USER_AGENT", "")    ua = parse(user_agent_string)    if ua.is_mobile:        device_type = "Mobile"    elif ua.is_tablet:        device_type = "Tablet"    elif ua.is_pc:        device_type = "Desktop"    elif ua.is_bot:        device_type = "Bot"    else:        device_type = "Unknown"    return {        "device_name": ua.device.family or "Unknown Device",        "device_type": device_type,        "browser": ua.browser.family or "Unknown Browser",        "browser_version": ".".join(map(str, ua.browser.version))        if ua.browser.version else "",        "operating_system": ua.os.family or "Unknown OS",        "os_version": ".".join(map(str, ua.os.version))        if ua.os.version else "",        "user_agent": user_agent_string,    }# =====================================================# LOGIN SUCCESS# =====================================================@receiver(user_logged_in)def log_user_login(sender, request, user, **kwargs):    if request and not request.session.session_key:        request.session.save()    current_session = request.session.session_key or ""    ip = get_client_ip(request)    location = get_ip_location(ip)    device = get_device_info(request)    trusted = LoginLogoutDeviceLog.objects.filter(        user=user,        ip_address=ip,        device_name=device["device_name"],        login_success=True    ).exists()    multiple = LoginLogoutDeviceLog.objects.filter(        user=user,        status="ACTIVE"    ).exclude(session_key=current_session).exists()    LoginLogoutDeviceLog.objects.create(        user=user,        ip_address=ip,        country=location["country"],        state=location["state"],        city=location["city"],        timezone_name=location["timezone"],        screen_name="Login Screen",        session_key=current_session,        login_time=now(),        last_activity=now(),        status="ACTIVE",        login_success=True,        device_name=device["device_name"],        device_type=device["device_type"],        browser=device["browser"],        browser_version=device["browser_version"],        operating_system=device["operating_system"],        os_version=device["os_version"],        user_agent=device["user_agent"],        is_trusted_device=trusted,        is_new_device=not trusted,        suspicious_login=not trusted,        multiple_session=multiple,    )# =====================================================# LOGOUT# =====================================================@receiver(user_logged_out)def log_user_logout(sender, request, user, **kwargs):    if not user:        return    session_key = request.session.session_key if request else ""    log = LoginLogoutDeviceLog.objects.filter(        user=user,        session_key=session_key,        status="ACTIVE"    ).last()    if log:        log.logout_time = now()        log.last_activity = now()        log.status = "LOGOUT"        log.save()# =====================================================# FAILED LOGIN# =====================================================@receiver(user_login_failed)def log_failed_login(sender, credentials, request, **kwargs):    username = credentials.get("username", "")    ip = get_client_ip(request)    location = get_ip_location(ip)    device = get_device_info(request)    user = User.objects.filter(username=username).first()    LoginLogoutDeviceLog.objects.create(        user=user if user else User.objects.first(),        ip_address=ip,        country=location["country"],        state=location["state"],        city=location["city"],        timezone_name=location["timezone"],        screen_name=f"Login Failed ({username})",        session_key="",        login_time=now(),        last_activity=now(),        status="FAILED",        login_success=False,        failed_reason="Invalid username or password",        remarks="Authentication failed",        device_name=device["device_name"],        device_type=device["device_type"],        browser=device["browser"],        browser_version=device["browser_version"],        operating_system=device["operating_system"],        os_version=device["os_version"],        user_agent=device["user_agent"],        suspicious_login=True,        is_new_device=True,        is_trusted_device=False,    )